<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';$error=null;$rows=[];$cats=[];$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category']??0);try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$set=ps23_settings($pdo,$ctx['organization_id']);if(empty($set['storefront_enabled']))throw new RuntimeException('The product portal is temporarily unavailable.');$rows=ps23_catalog($pdo,$ctx['organization_id'],$q,$category);$cats=ps23_categories($pdo,$ctx['organization_id']);}catch(Throwable $e){$error=$e->getMessage();}
function avlabel(string $s):string{return match($s){'available'=>'Available','limited'=>'Limited availability','unavailable'=>'Currently unavailable',default=>'Availability confirmed at review'};}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Browse Healthcare Wellness Club products with source-listed MRP and submit a product order request for club confirmation."><title>Products - Healthcare Wellness Club</title><link rel="stylesheet" href="store.css"></head><body><header class="store-top"><div class="store-bar"><a class="store-brand" href="../index.html"><img src="../img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Public Product Portal</small></span></a><div class="store-actions"><a class="store-btn" href="status.php">Track Request</a><a class="store-btn primary" href="cart.php">Cart (<span data-cart-count>0</span>)</a></div></div></header><main class="store-shell"><section class="store-hero"><div class="store-kicker">STEP 23 • PRODUCT PORTAL</div><h1>Browse products with source-listed MRP, then send an order request for confirmation.</h1><p>Prices shown here use the current active India price-list MRP in the Business OS. This portal does not silently assign Preferred/Associate eligibility, collect payment, estimate tax or expose internal cost and stock quantities.</p></section><?php if($error):?><div class="notice bad"><?=ps23_h($error)?></div><?php else:?><form class="store-toolbar" method="get"><input class="store-input" name="q" value="<?=ps23_h($q)?>" placeholder="Search product, stock number or category"><select class="store-select" name="category"><option value="0">All categories</option><?php foreach($cats as$c):?><option value="<?=$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=ps23_h($c['category_name'])?></option><?php endforeach;?></select><button class="store-btn primary">Search</button></form><div class="notice">Final availability, eligible customer pricing, taxes and payment are confirmed separately by the club. Home delivery below 100 VP may carry the source-listed ₹100 delivery charge excluding taxes where applicable.</div><section class="store-grid"><?php foreach($rows as$r):?><article class="product-card"><div class="product-image"><?php if(!empty($r['verified_image'])):?><img src="<?=ps23_h($r['verified_image'])?>" alt="<?=ps23_h($r['product_name'])?>" loading="lazy"><?php else:?><div class="product-placeholder">HWC</div><?php endif;?></div><div class="product-body"><span class="pill <?=ps23_h($r['availability_status'])?>"><?=ps23_h(avlabel($r['availability_status']))?></span><div class="meta"><?=ps23_h($r['category_name'])?> • Stock <?=ps23_h($r['sku'])?></div><h2><?=ps23_h($r['product_name'])?></h2><div><span class="price"><?=ps23_money($r['mrp'])?></span> <span class="vp"><?=ps23_h(rtrim(rtrim(number_format((float)$r['volume_points'],3,'.',''),'0'),'.'))?> VP</span></div><div class="meta">Price effective <?=ps23_h($r['effective_from'])?> • MRP</div><div class="product-actions"><a class="store-btn" href="product.php?id=<?=$r['id']?>">Details</a><button class="store-btn primary" type="button" data-add-product="<?=$r['id']?>" <?=$r['availability_status']==='unavailable'?'disabled':''?>>Add</button></div></div></article><?php endforeach;?><?php if(!$rows):?><div class="card empty" style="grid-column:1/-1">No matching active products.</div><?php endif;?></section><?php endif;?></main><footer class="store-footer">Healthcare Wellness Club • Product information and order requests only • Final confirmation by the club</footer><script src="store.js"></script></body></html>